     1	package br.com.maralta.controller;
     2	
     3	import br.com.maralta.domain.Reservation;
     4	import br.com.maralta.domain.Room;
     5	import br.com.maralta.repository.RoomRepository;
     6	import br.com.maralta.service.InvalidRequestException;
     7	import br.com.maralta.service.ReservationService;
     8	import io.javalin.http.Context;
     9	
    10	import java.math.BigDecimal;
    11	import java.time.LocalDate;
    12	import java.time.YearMonth;
    13	import java.time.format.DateTimeFormatter;
    14	import java.time.format.DateTimeParseException;
    15	import java.util.List;
    16	
    17	public class ReportController {
    18	
    19	    private final ReservationService reservationService;
    20	    private final RoomRepository roomRepository;
    21	
    22	    public ReportController(ReservationService reservationService, RoomRepository roomRepository) {
    23	        this.reservationService = reservationService;
    24	        this.roomRepository = roomRepository;
    25	    }
    26	
    27	    public void occupancyReport(Context ctx) {
    28	        String dateParam = ctx.queryParam("date");
    29	        if (dateParam == null || dateParam.isEmpty()) {
    30	            throw new InvalidRequestException("Date parameter is required");
    31	        }
    32	
    33	        LocalDate date;
    34	        try {
    35	            date = LocalDate.parse(dateParam, DateTimeFormatter.ISO_LOCAL_DATE);
    36	        } catch (DateTimeParseException e) {
    37	            throw new InvalidRequestException("Invalid date format. Expected: yyyy-MM-dd");
    38	        }
    39	
    40	        List<Reservation> reservations = reservationService.getOccupancyByNight(date);
    41	        List<Room> allRooms = roomRepository.findAll();
    42	
    43	        StringBuilder csv = new StringBuilder();
    44	        csv.append("room,type,reservation,check_in,check_out\n");
    45	
    46	        for (Reservation reservation : reservations) {
    47	            Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    48	            csv.append(String.format("%s,%s,%d,%s,%s\n",
    49	                reservation.getRoomNumber(),
    50	                room.getType().name(),
    51	                reservation.getId(),
    52	                reservation.getCheckIn(),
    53	                reservation.getCheckOut()
    54	            ));
    55	        }
    56	
    57	        csv.append(String.format("total,%d/%d\n", reservations.size(), allRooms.size()));
    58	
    59	        ctx.contentType("text/csv; charset=utf-8");
    60	        ctx.result(csv.toString());
    61	    }
    62	
    63	    public void revenueReport(Context ctx) {
    64	        String monthParam = ctx.queryParam("month");
    65	        if (monthParam == null || monthParam.isEmpty()) {
    66	            throw new InvalidRequestException("Month parameter is required");
    67	        }
    68	
    69	        YearMonth month;
    70	        try {
    71	            month = YearMonth.parse(monthParam, DateTimeFormatter.ofPattern("yyyy-MM"));
    72	        } catch (DateTimeParseException e) {
    73	            throw new InvalidRequestException("Invalid month format. Expected: yyyy-MM");
    74	        }
    75	
    76	        List<Reservation> reservations = reservationService.getRevenueByMonth(month);
    77	
    78	        StringBuilder csv = new StringBuilder();
    79	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    80	
    81	        BigDecimal total = BigDecimal.ZERO;
    82	
    83	        for (Reservation reservation : reservations) {
    84	            BigDecimal amount = reservation.getAmountPaid().subtract(
    85	                reservation.getRefund() != null ? reservation.getRefund() : BigDecimal.ZERO
    86	            );
    87	
    88	            csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
    89	                reservation.getId(),
    90	                reservation.getRoomNumber(),
    91	                reservation.getCheckIn(),
    92	                reservation.getCheckOut(),
    93	                reservation.getStatus().name(),
    94	                formatDecimal(amount)
    95	            ));
    96	
    97	            total = total.add(amount);
    98	        }
    99	
   100	        csv.append(String.format("total,%s\n", formatDecimal(total)));
   101	
   102	        ctx.contentType("text/csv; charset=utf-8");
   103	        ctx.result(csv.toString());
   104	    }
   105	
   106	    private String formatDecimal(BigDecimal value) {
   107	        return value.toString();
   108	    }
   109	}
