     1	package br.com.maralta.controller;
     2	
     3	import br.com.maralta.controller.dto.CreateReservationRequest;
     4	import br.com.maralta.controller.dto.DocumentResponse;
     5	import br.com.maralta.controller.dto.ReservationResponse;
     6	import br.com.maralta.domain.RatePlanType;
     7	import br.com.maralta.domain.Reservation;
     8	import br.com.maralta.domain.Room;
     9	import br.com.maralta.repository.RoomRepository;
    10	import br.com.maralta.service.ReservationService;
    11	import io.javalin.http.Context;
    12	
    13	public class ReservationController {
    14	
    15	    private final ReservationService reservationService;
    16	    private final RoomRepository roomRepository;
    17	
    18	    public ReservationController(ReservationService reservationService, RoomRepository roomRepository) {
    19	        this.reservationService = reservationService;
    20	        this.roomRepository = roomRepository;
    21	    }
    22	
    23	    public void createReservation(Context ctx) {
    24	        CreateReservationRequest request = ctx.bodyAsClass(CreateReservationRequest.class);
    25	
    26	        RatePlanType ratePlan = RatePlanType.valueOf(request.ratePlan());
    27	
    28	        Reservation reservation = reservationService.createReservation(
    29	            request.roomNumber(),
    30	            request.guestName(),
    31	            request.guestEmail(),
    32	            request.guestCpf(),
    33	            request.checkIn(),
    34	            request.checkOut(),
    35	            request.guests(),
    36	            ratePlan,
    37	            request.companyCode()
    38	        );
    39	
    40	        ctx.status(201).json(ReservationResponse.from(reservation));
    41	    }
    42	
    43	    public void getReservation(Context ctx) {
    44	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    45	        Reservation reservation = reservationService.getReservation(id);
    46	        ctx.json(ReservationResponse.from(reservation));
    47	    }
    48	
    49	    public void confirmReservation(Context ctx) {
    50	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    51	        Reservation reservation = reservationService.confirmReservation(id);
    52	        ctx.json(ReservationResponse.from(reservation));
    53	    }
    54	
    55	    public void cancelReservation(Context ctx) {
    56	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    57	        Reservation reservation = reservationService.cancelReservation(id);
    58	        ctx.json(ReservationResponse.from(reservation));
    59	    }
    60	
    61	    public void checkIn(Context ctx) {
    62	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    63	        Reservation reservation = reservationService.checkIn(id);
    64	        ctx.json(ReservationResponse.from(reservation));
    65	    }
    66	
    67	    public void checkOut(Context ctx) {
    68	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    69	        Reservation reservation = reservationService.checkOut(id);
    70	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    71	        ctx.json(DocumentResponse.from(reservation, room));
    72	    }
    73	
    74	    public void getDocument(Context ctx) {
    75	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    76	        Reservation reservation = reservationService.getReservation(id);
    77	
    78	        if (reservation.getAmountPaid().compareTo(java.math.BigDecimal.ZERO) == 0) {
    79	            throw new br.com.maralta.service.OperationNotAllowedException(
    80	                "Document is only available for paid reservations");
    81	        }
    82	
    83	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
    84	        ctx.json(DocumentResponse.from(reservation, room));
    85	    }
    86	}
