    19	public class ReservationService {
    20	
    21	    private final ReservationRepository reservationRepository;
    22	    private final RoomRepository roomRepository;
    23	    private final MessageService messageService;
    24	
    25	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    26	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(new Locale("pt", "BR"));
    27	
    28	    public ReservationService(ReservationRepository reservationRepository,
    29	                             RoomRepository roomRepository,
    30	                             MessageService messageService) {
    31	        this.reservationRepository = reservationRepository;
    32	        this.roomRepository = roomRepository;
