    35	
    36	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    37	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    38	                                        int guests, RatePlanType ratePlanType, String companyCode) {
    39	
    40	        Room room = roomRepository.findByNumber(roomNumber)
    41	            .orElseThrow(() -> new RoomNotFoundException("Room not found: " + roomNumber));
    42	
    43	        if (guests < 1) {
    44	            throw new InvalidRequestException("At least one guest is required");
    45	        }
    46	
    47	        if (guests > room.getCapacity()) {
    48	            throw new CapacityExceededException("Room capacity exceeded");
    49	        }
    50	
    51	        if (!checkOut.isAfter(checkIn)) {
    52	            throw new InvalidRequestException("Check-out must be after check-in");
    53	        }
    54	
    55	        Reservation reservation = new Reservation();
    56	        reservation.setRoomNumber(roomNumber);
    57	        reservation.setGuestName(guestName);
    58	        reservation.setGuestEmail(guestEmail);
    59	        reservation.setGuestCpf(guestCpf);
    60	        reservation.setCheckIn(checkIn);
    61	        reservation.setCheckOut(checkOut);
    62	        reservation.setGuests(guests);
    63	        reservation.setRatePlan(ratePlanType);
    64	        reservation.setCompanyCode(companyCode);
    65	        reservation.calculateNights();
    66	
    67	        RatePlan ratePlan = RatePlanFactory.create(ratePlanType);
    68	
    69	        try {
    70	            ratePlan.validate(checkIn, checkOut, reservation.getNights(), room.getType(), companyCode);
    71	        } catch (IllegalArgumentException e) {
    72	            throw new InvalidRequestException(e.getMessage());
    73	        }
    74	
    75	        BigDecimal subtotal = ratePlan.calculateSubtotal(checkIn, checkOut, reservation.getNights(), room.getType());
    76	        reservation.setSubtotal(subtotal);
    77	
    78	        BigDecimal discount;
    79	        if (ratePlanType == RatePlanType.CORPORATE && ratePlan instanceof CorporateRatePlan corporatePlan) {
    80	            discount = corporatePlan.calculateDiscount(subtotal, companyCode);
    81	        } else {
    82	            discount = ratePlan.calculateDiscount(subtotal);
    83	        }
    84	        reservation.setDiscount(discount);
    85	
    86	        BigDecimal total = subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    87	        reservation.setTotal(total);
    88	
    89	        List<Reservation> overlapping = reservationRepository.findOverlapping(
    90	            roomNumber, checkIn, checkOut, null);
    91	
    92	        if (!overlapping.isEmpty()) {
    93	            throw new RoomUnavailableException("Room is not available for the selected dates");
    94	        }
    95	
    96	        return reservationRepository.save(reservation);
    97	    }
