   104	    public Reservation confirmReservation(Long id) {
   105	        Reservation reservation = getReservation(id);
   106	
   107	        if (reservation.getStatus() != ReservationStatus.PENDING) {
   108	            throw new OperationNotAllowedException("Only pending reservations can be confirmed");
   109	        }
   110	
   111	        reservation.setStatus(ReservationStatus.CONFIRMED);
   112	        reservation.setAmountPaid(reservation.getTotal());
   113	        reservationRepository.save(reservation);
   114	
   115	        sendConfirmationEmail(reservation);
   116	
   117	        return reservation;
   118	    }
   119	
   120	    public Reservation cancelReservation(Long id) {
   121	        Reservation reservation = getReservation(id);
   122	
   123	        if (reservation.getStatus() != ReservationStatus.PENDING
   124	            && reservation.getStatus() != ReservationStatus.CONFIRMED) {
   125	            throw new OperationNotAllowedException("Only pending or confirmed reservations can be cancelled");
   126	        }
   127	
   128	        reservation.setStatus(ReservationStatus.CANCELLED);
   129	
   130	        RatePlan ratePlan = RatePlanFactory.create(reservation.getRatePlan());
   131	        BigDecimal refund = ratePlan.calculateRefund(reservation.getAmountPaid());
   132	        reservation.setRefund(refund);
   133	
   134	        return reservationRepository.save(reservation);
