   138	        Reservation reservation = getReservation(id);
   139	
   140	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   141	            throw new OperationNotAllowedException("Only confirmed reservations can be checked in");
   142	        }
   143	
   144	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   145	        return reservationRepository.save(reservation);
   146	    }
   147	
   148	    public Reservation checkOut(Long id) {
   149	        Reservation reservation = getReservation(id);
   150	
   151	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   152	            throw new OperationNotAllowedException("Only checked-in reservations can be checked out");
   153	        }
   154	
   155	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   156	        return reservationRepository.save(reservation);
   157	    }
   158	
   159	    public String generateDocument(Long id) {
   160	        Reservation reservation = getReservation(id);
   161	
   162	        if (reservation.getStatus() == ReservationStatus.PENDING
   163	            || reservation.getStatus() == ReservationStatus.CANCELLED) {
   164	            throw new OperationNotAllowedException("Document is only available for paid reservations");
   165	        }
   166	
   167	        return buildDocument(reservation);
   168	    }
   169	
   170	    private void sendConfirmationEmail(Reservation reservation) {
   171	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
   172	        String document = buildDocument(reservation);
   173	
   174	        String body = String.format("""
   175	            Olá, %s!
   176	
   177	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
   178	
   179	            %s
   180	
   181	            A entrada é a partir das 14h, e a saída, até as 12h.
   182	            Até breve!""",
   183	            reservation.getGuestName(),
   184	            document);
   185	
   186	        messageService.sendEmail(
   187	            reservation.getGuestEmail(),
   188	            "Reserva confirmada - Pousada Maré Alta",
   189	            body
   190	        );
   191	    }
   192	
   193	    private String buildDocument(Reservation reservation) {
   194	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
   195	
   196	        StringBuilder doc = new StringBuilder();
   197	        doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
   198	        doc.append("Hóspede: ").append(reservation.getGuestName())
   199	           .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
   200	        doc.append("Quarto: ").append(reservation.getRoomNumber())
   201	           .append(" (").append(room.getType().name()).append(")\n");
   202	        doc.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMATTER))
   203	           .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMATTER))
   204	           .append(" | ").append(reservation.getNights())
   205	           .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
   206	        doc.append("Diárias: ").append(formatCurrency(reservation.getSubtotal())).append("\n");
   207	
   208	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   209	            doc.append("Desconto: ").append(formatCurrency(reservation.getDiscount())).append("\n");
   210	        }
   211	
   212	        doc.append("Total: ").append(formatCurrency(reservation.getTotal()));
   213	
   214	        return doc.toString();
   215	    }
   216	
   217	    private String formatCpf(String cpf) {
   218	        if (cpf.length() == 11) {
   219	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
   220	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
   221	        }
   222	        return cpf;
   223	    }
   224	
   225	    private String formatCurrency(BigDecimal amount) {
   226	        return CURRENCY_FORMAT.format(amount);
   227	    }
