    10	public class CorporateRatePlan implements RatePlan {
    11	
    12	    private static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
    13	        "TECNOSUL", new BigDecimal("0.12"),
    14	        "AGROVALE", new BigDecimal("0.18"),
    15	        "FARMAVIDA", new BigDecimal("0.25")
    16	    );
    17	
    18	    @Override
    19	    public void validate(LocalDate checkIn, LocalDate checkOut, int nights, RoomType roomType, String companyCode) {
    20	        if (companyCode == null || companyCode.trim().isEmpty()) {
    21	            throw new IllegalArgumentException("Company code is required for corporate rate plan");
    22	        }
    23	
    24	        if (!COMPANY_DISCOUNTS.containsKey(companyCode)) {
    25	            throw new IllegalArgumentException("Invalid company code: " + companyCode);
    26	        }
    27	    }
    28	
    29	    @Override
    30	    public BigDecimal calculateSubtotal(LocalDate checkIn, LocalDate checkOut, int nights, RoomType roomType) {
    31	        BigDecimal baseRate = roomType.getNightlyRate();
    32	        BigDecimal subtotal = BigDecimal.ZERO;
    33	
    34	        LocalDate currentDate = checkIn;
    35	        for (int i = 0; i < nights; i++) {
    36	            BigDecimal nightRate = baseRate;
    37	            if (isHighSeason(currentDate)) {
    38	                nightRate = nightRate.multiply(new BigDecimal("1.20"));
    39	            }
    40	            nightRate = nightRate.setScale(2, RoundingMode.HALF_EVEN);
    41	            subtotal = subtotal.add(nightRate);
    42	            currentDate = currentDate.plusDays(1);
    43	        }
    44	
    45	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    46	    }
    47	
    48	    @Override
    49	    public BigDecimal calculateDiscount(BigDecimal subtotal) {
    50	        return BigDecimal.ZERO;
    51	    }
    52	
    53	    public BigDecimal calculateDiscount(BigDecimal subtotal, String companyCode) {
    54	        BigDecimal discountRate = COMPANY_DISCOUNTS.get(companyCode);
    55	        if (discountRate == null) {
    56	            return BigDecimal.ZERO;
    57	        }
    58	
    59	        BigDecimal discount = subtotal.multiply(discountRate);
    60	        return discount.setScale(2, RoundingMode.HALF_EVEN);
    61	    }
    62	
    63	    @Override
    64	    public BigDecimal calculateRefund(BigDecimal amountPaid) {
    65	        return amountPaid;
    66	    }
    67	}
