    36	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    37	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    38	                                        int guests, RatePlanType ratePlanType, String companyCode) {
    39	
    40	        Room room = roomRepository.findByNumber(roomNumber)
