     9	public class DatabaseInitializer {
    10	
    11	    public static void initialize(Connection connection) {
    12	        try {
    13	            createTables(connection);
    14	            seedRooms(connection);
    15	        } catch (SQLException e) {
    16	            throw new RuntimeException("Failed to initialize database", e);
    17	        }
    18	    }
    19	
    20	    private static void createTables(Connection connection) throws SQLException {
    21	        String createRoomsTable = """
    22	            CREATE TABLE IF NOT EXISTS rooms (
    23	                number VARCHAR(10) PRIMARY KEY,
    24	                type VARCHAR(20) NOT NULL
    25	            )
    26	            """;
    27	
    28	        String createReservationsTable = """
    29	            CREATE TABLE IF NOT EXISTS reservations (
    30	                id BIGSERIAL PRIMARY KEY,
    31	                room_number VARCHAR(10) NOT NULL,
    32	                guest_name VARCHAR(255) NOT NULL,
    33	                guest_email VARCHAR(255) NOT NULL,
    34	                guest_cpf VARCHAR(14) NOT NULL,
    35	                check_in DATE NOT NULL,
    36	                check_out DATE NOT NULL,
    37	                guests INTEGER NOT NULL,
    38	                rate_plan VARCHAR(50) NOT NULL,
    39	                company_code VARCHAR(50),
    40	                nights INTEGER NOT NULL,
    41	                subtotal DECIMAL(10, 2) NOT NULL,
    42	                discount DECIMAL(10, 2) NOT NULL,
    43	                total DECIMAL(10, 2) NOT NULL,
    44	                status VARCHAR(20) NOT NULL,
    45	                amount_paid DECIMAL(10, 2) NOT NULL DEFAULT 0,
    46	                refund DECIMAL(10, 2),
    47	                FOREIGN KEY (room_number) REFERENCES rooms(number)
    48	            )
    49	            """;
    50	
    51	        String createMessagesTable = """
    52	            CREATE TABLE IF NOT EXISTS messages (
    53	                id BIGSERIAL PRIMARY KEY,
    54	                channel VARCHAR(20) NOT NULL,
    55	                recipient VARCHAR(255) NOT NULL,
    56	                subject TEXT NOT NULL,
    57	                body TEXT NOT NULL
    58	            )
    59	            """;
    60	
    61	        try (Statement stmt = connection.createStatement()) {
    62	            stmt.execute(createRoomsTable);
    63	            stmt.execute(createReservationsTable);
    64	            stmt.execute(createMessagesTable);
    65	        }
    66	    }
    67	
    68	    private static void seedRooms(Connection connection) throws SQLException {
    69	        String checkRooms = "SELECT COUNT(*) as count FROM rooms";
    70	
    71	        try (Statement stmt = connection.createStatement();
    72	             var rs = stmt.executeQuery(checkRooms)) {
    73	            if (rs.next() && rs.getInt("count") > 0) {
    74	                return;
    75	            }
    76	        }
    77	
    78	        String insertRooms = """
    79	            INSERT INTO rooms (number, type) VALUES
    80	            ('101', 'STANDARD'),
    81	            ('102', 'STANDARD'),
    82	            ('201', 'DELUXE'),
    83	            ('202', 'DELUXE'),
    84	            ('301', 'SUITE')
    85	            """;
    86	
